export {
  InputOTP,
  InputOTPGroup,
  InputOTPSeparator,
  InputOTPSlot,
  type InputOTPSlotProps,
} from "./input-otp";
export {
  OTPInputContext,
  useInputOtp,
  useInputOtpRoot,
  useInputOtpSlot,
  type InputOTPProps,
  type InputOtpRootReturn,
  type InputOtpSlotReturn,
  type OtpApi,
  type OtpSlotState,
} from "./useInputOtp";

import { cc } from "sinwan/component";
import { Show } from "sinwan/control-flow";
import { Minus } from "lucide";

import { Icon } from "@/lib/icons";
import { cn } from "@/lib/utils";
import {
  useInputOtpRoot,
  useInputOtpSlot,
  type InputOTPProps,
} from "./useInputOtp";

export const InputOTP = cc<InputOTPProps>((props) => {
  const root = useInputOtpRoot(props);

  return (
    <div
      data-slot="input-otp"
      class={cn(
        "cn-input-otp relative flex items-center has-disabled:opacity-50",
        props.containerClass,
      )}
      aria-invalid={props["aria-invalid"]}
    >
      <input
        ref={root.setInput}
        data-slot="input-otp-hidden"
        class={cn(
          "absolute inset-0 h-full w-full cursor-default opacity-0 disabled:cursor-not-allowed",
          props.class,
        )}
        value={root.value.value}
        maxLength={props.maxLength ?? 6}
        disabled={props.disabled}
        inputMode={props.inputMode ?? "numeric"}
        autocomplete={props.autocomplete ?? "one-time-code"}
        spellcheck={false}
        aria-invalid={props["aria-invalid"]}
        onfocus={root.onFocus}
        onblur={root.onBlur}
        oninput={root.onInput}
        onpaste={root.onPaste}
      />
      <div class="flex items-center" onclick={root.onContainerClick}>
        {props.children}
      </div>
    </div>
  );
});

export function InputOTPGroup({
  class: className,
  ...props
}: JSX.IntrinsicElements["div"]) {
  return (
    <div
      data-slot="input-otp-group"
      class={cn(
        "flex items-center rounded-lg has-aria-invalid:border-destructive has-aria-invalid:ring-3 has-aria-invalid:ring-destructive/20 dark:has-aria-invalid:ring-destructive/40",
        className,
      )}
      {...props}
    />
  );
}

export type InputOTPSlotProps = JSX.IntrinsicElements["div"] & {
  index: number;
};

export const InputOTPSlot = cc<InputOTPSlotProps>(
  ({ index, class: className, ...props }) => {
    const slot = useInputOtpSlot(() => index);

    return (
      <div
        data-slot="input-otp-slot"
        data-active={slot.isActive.value ? "true" : undefined}
        class={cn(
          "relative flex size-8 items-center justify-center border-y border-r border-input text-sm transition-all outline-none first:rounded-l-lg first:border-l last:rounded-r-lg aria-invalid:border-destructive data-[active=true]:z-10 data-[active=true]:border-ring data-[active=true]:ring-3 data-[active=true]:ring-ring/50 data-[active=true]:aria-invalid:border-destructive data-[active=true]:aria-invalid:ring-destructive/20 dark:bg-input/30 dark:data-[active=true]:aria-invalid:ring-destructive/40",
          className,
        )}
        {...props}
      >
        {slot.char.value}
        <Show when={slot.hasFakeCaret.value}>
          <div class="pointer-events-none absolute inset-0 flex items-center justify-center">
            <div class="h-4 w-px animate-caret-blink bg-foreground duration-1000" />
          </div>
        </Show>
      </div>
    );
  },
);

export function InputOTPSeparator(props: JSX.IntrinsicElements["div"]) {
  return (
    <div
      data-slot="input-otp-separator"
      class="flex items-center [&_svg:not([class*='size-'])]:size-4"
      role="separator"
      {...props}
    >
      <Icon icon={Minus} />
    </div>
  );
}

import {
  getRawProps,
  inject,
  provide,
  type InjectionKey,
  type SinwanNode,
} from "sinwan/component";
import {
  computed,
  signal,
  unwrap,
  type Computed,
  type Signal,
} from "sinwan/reactivity";

export type OtpSlotState = {
  char: string;
  hasFakeCaret: boolean;
  isActive: boolean;
};

export type OtpApi = {
  value: Signal<string>;
  maxLength: number;
  slots: () => OtpSlotState[];
  focus: () => void;
};

export const OTPInputContext: InjectionKey<OtpApi> = Symbol("sinwan-ui.input-otp");

export type InputOTPProps = {
  maxLength?: number;
  value?: string;
  onChange?: (value: string) => void;
  onComplete?: (value: string) => void;
  class?: string;
  containerClass?: string;
  disabled?: boolean;
  children?: SinwanNode;
  pattern?: string;
  inputMode?: JSX.IntrinsicElements["input"]["inputMode"];
  autocomplete?: string;
  "aria-invalid"?: boolean | "true" | "false";
};

export type InputOtpRootReturn = {
  otp: OtpApi;
  value: Signal<string>;
  maxLength: number;
  setInput: (element: HTMLInputElement | null) => void;
  onFocus: () => void;
  onBlur: () => void;
  onInput: (event: Event) => void;
  onPaste: (event: ClipboardEvent) => void;
  onContainerClick: () => void;
};

export type InputOtpSlotReturn = {
  char: Computed<string>;
  isActive: Computed<boolean>;
  hasFakeCaret: Computed<boolean>;
};

function sanitize(value: string, maxLength: number, pattern?: string): string {
  let next = value;
  if (!pattern) {
    next = value.replace(/\s/g, "");
    return next.slice(0, maxLength);
  }
  try {
    const re = new RegExp(pattern, "g");
    next = (next.match(re) ?? []).join("");
  } catch {
    next = value.replace(/\s/g, "");
  }
  return next.slice(0, maxLength);
}

export function useInputOtpRoot(props: InputOTPProps): InputOtpRootReturn {
  const value = signal(props.value ?? "");
  if (props.value !== undefined) value.value = props.value;

  let inputEl: HTMLInputElement | null = null;
  const focused = signal(false);
  const length = () => props.maxLength ?? 6;

  const setValue = (next: string) => {
    const maxLength = length();
    const cleaned = sanitize(next, maxLength, props.pattern);
    value.value = cleaned;
    const raw = getRawProps(props);
    const onChange = unwrap(raw.onChange);
    const onComplete = unwrap(raw.onComplete);
    if (typeof onChange === "function") onChange(cleaned);
    if (cleaned.length >= maxLength && typeof onComplete === "function") {
      onComplete(cleaned);
    }
  };

  const slots = (): OtpSlotState[] => {
    const maxLength = length();
    const current = value.value;
    const activeIndex = Math.min(current.length, maxLength - 1);
    return Array.from({ length: maxLength }, (_, index) => ({
      char: current[index] ?? "",
      isActive: focused.value && index === activeIndex,
      hasFakeCaret:
        focused.value && index === activeIndex && current.length < maxLength
          ? index === current.length
          : focused.value &&
            index === activeIndex &&
            current.length === maxLength &&
            index === maxLength - 1,
    }));
  };

  const otp: OtpApi = {
    value,
    get maxLength() {
      return length();
    },
    slots,
    focus: () => inputEl?.focus(),
  };
  provide(OTPInputContext, otp);

  return {
    otp,
    value,
    get maxLength() {
      return length();
    },
    setInput: (element) => {
      inputEl = element;
    },
    onFocus: () => {
      focused.value = true;
    },
    onBlur: () => {
      focused.value = false;
    },
    onInput: (event) => {
      const target = event.target as HTMLInputElement;
      setValue(target.value);
    },
    onPaste: (event) => {
      event.preventDefault();
      const text = event.clipboardData?.getData("text") ?? "";
      setValue(text);
    },
    onContainerClick: () => {
      if (!props.disabled) inputEl?.focus();
    },
  };
}

export function useInputOtp(consumer = "useInputOtp"): OtpApi {
  const otp = inject(OTPInputContext);
  if (!otp) {
    throw new Error(`${consumer} must be used within InputOTP`);
  }
  return otp;
}

export function useInputOtpSlot(index: () => number): InputOtpSlotReturn {
  const otp = useInputOtp("InputOTPSlot");
  const slot = computed(() => otp.slots()[index()]);
  return {
    char: computed(() => slot.value?.char ?? ""),
    isActive: computed(() => Boolean(slot.value?.isActive)),
    hasFakeCaret: computed(() => Boolean(slot.value?.hasFakeCaret)),
  };
}
